main.script:
$(function() {
  initializeScroller(mobileDevice, '#search_menu_scroller');
  active_nav_item = 'movie';

  History.Adapter.bind(window, 'statechange', function() {
    var State = History.getState();
    changeSearchTabs(State.data.media_type);
  });

    $('a.search_tab').on('click', function(e) {
      e.preventDefault();

        window.scrollTo(0, 0);

        History.pushState({ media_type: active_nav_item }, document.title, '/search?query=');

      selected_media_type = $(this).prop('id')
      changeSearchTabs(selected_media_type);

      $('ul.with_counts li').removeClass('selected');
      $(this).parent().addClass('selected');

        History.pushState({ media_type: selected_media_type }, document.title, '/search/' + selected_media_type + '?query=');

    });
});

body.script:
      function showSearch(state) {
        if ( state ) {
          $('header').removeClass('nav-up').addClass('nav-down');
          $('li.search_buttons a.close').removeClass('hide');
          $('li.search_buttons a.search').addClass('hide');
          $('div.search_bar').removeClass('hide');
          $("#search_v4").data("kendoAutoComplete").focus();
        } else {
          $('li.search_buttons a.close').addClass('hide');
          $('li.search_buttons a.search').removeClass('hide');
          $('div.search_bar').addClass('hide');
        }
      }

      $(function() {
        jQuery.timeago.settings.allowFuture = true;
        $("time.timeago").timeago();

        var didScroll;
        var lastScrollTop = 0;
        var delta = 10;
        var navbarHeight = $('header').outerHeight();

        $(window).scroll(function(event){
          didScroll = true;
        });

        setInterval(function() {
          if (didScroll) {
            hasScrolled();
            didScroll = false;
          }
        }, 250);

        function hasScrolled() {
          var st = $(this).scrollTop();

          if ( Math.abs(lastScrollTop - st) <= delta )
            return;

          if ( st > lastScrollTop && st > navbarHeight ) {
            $('header').removeClass('nav-down').addClass('nav-up');
          } else {
            if ( st + $(window).height() < $(document).height() ) {
              $('header').removeClass('nav-up').addClass('nav-down');
            }
          }

          lastScrollTop = st;
        }

        var hover_tooltip = $('li.user a.no_click.tooltip_hover').kendoTooltip({
          position: 'bottom',
          show: function(e) {
            $("div.k-tooltip-button").addClass('hide');
            this.popup.element.addClass("tmdb_theme_white nowrap");
            this.element.removeClass('keyboard');
          }
        }).data("kendoTooltip");

        $('button').on('click', function(e) {
            var redirect_url = $(this).data('redirect-url');
            if (redirect_url === undefined) {
              return
            }

            window.location = redirect_url;
          });

        $('li.user a.no_click').kendoTooltip({
          autoHide: false,
          showOn: 'click',
          width: 180,
          position: 'bottom',
          content: function() {
            return $("#settings_tooltip").html();
          },
          show: function(e) {
            hover_tooltip.hide();
            $("div.k-tooltip-button").addClass('hide');
            this.popup.element.addClass("tmdb_theme_white no_pad");

            if (this.element.hasClass('keyboard')) {
              this.popup.element.find('p a')[0].focus();
            }
          }
        });

        $('li.translate').kendoTooltip({
          autoHide: false,
          content: {
            url: '/translation-popup?media_type=&media_id=&referral=/search'
          },
          showOn: 'click',
          width: 300,
          position: 'bottom',
          show: function(e) {
            this.popup.element.addClass("min_100px_height tmdb_theme_white flex");
          }
        });

        $('li.new_buttons').kendoTooltip({
          autoHide: false,
          showOn: 'click',

          position: 'bottom',
          content: function() {
            return $("#new_media_template").html();
          },
          show: function(e) {
            $("div.k-tooltip-button").addClass('hide');
            this.popup.element.addClass("tmdb_theme_white no_pad");
          }
        });


        $("body").on('click', 'a.no_click', function(e) {
          e.preventDefault();
        });

        $("ul > li").hover(function() {
          $(this).find("ul.sub_nav.hide").toggle();
        });


        var notification = $("#notification").kendoNotification({
          position: {
            top: 0,
            right: 10
          },
          animation: false,
          autoHideAfter: 5000,
          templates: [{
            type: "error",
            template: $("#errorTemplate").html()
          },{
            type: "success",
            template: $("#successTemplate").html()
          }]
        }).data("kendoNotification");

        showSuccess = function(message, title) {
          if (title === undefined) {
            title = 'Success';
          }

          return notification.show({
            title: title,
            message: message
          }, "success");
        };

        showError = function(message, title) {
          if (title === undefined) {
            title = 'Error';
          }

          return notification.show({
            title: title,
            message: message
          }, "error");
        };

        var keyboard_shortcut_popup = $('#keyboard_shortcuts_popup div.content').kendoWindow({
          title: 'Keyboard Shortcuts',
          width: mobileDevice ? "100%" : "90vw",
          maxWidth: mobileDevice ? "100%" : "1400px",
          actions: [ "Close" ],
          modal: true,
          draggable: false,
          resizable: false,
          visible: false,
          pinned: true,
          animation: {
            open: {
              effects: "fade:in"
            },
            close: {
              effects: "fade:out"
            }
          },
          open: function() {
            $('body').addClass('monochrome');
          },
          close: function() {
            $('body').removeClass('monochrome');
          }
        }).data("kendoWindow").center();

        $('#keyboard_shortcuts').on('click', function() {
          keyboard_shortcut_popup.open();
        });

           $("#toggle_keyboard_shortcuts").prop('checked', true);

        $("#toggle_keyboard_shortcuts").on('change', function (e) {
          var checkboxState = $(this).prop('checked');
          $.post({
            url: '/settings/toggle-keyboard-shortcuts',
            dataType: "json",
            data: {
              keyboard_shortcuts_enabled: checkboxState
            }
          }).fail(function () {
            showError('There was a problem.');
          }).done(function (response) {
            if (response.failure) {
              showError('There was a problem.');
            }
            if (response.success) {
              showSuccess('');
              window.location.reload();
            }
          });
        });

        var seach_redirect_template = "/search{0}?query={1}";
        var processing_selected_item = false;
        var processing_manually_selected_item = false;

        window.onbeforeunload = function() {
          processing_selected_item = false;
          processing_manually_selected_item = false;
        }

        function executeSearch(url) {
          window.location = url;
        }

        function processSelectedItem(event) {
          if (event == '') {
            return;
          }

          var dataItem = null;
          var media_type = null;
          var search_value = '';
          var selected_item = '';

          if (event == null) {
            dataItem = $("#search_v4").data("kendoAutoComplete").value();
          } else {
            dataItem = event.dataItem;
          }

          // This is the returned items from trending, when no search has been performed
          if ( typeof(dataItem) == 'string' ) {
            try {
              var search_value = $(dataItem).data('search-name');
              var media_type = $(dataItem).data('media-type');
            } catch(error) {
              var search_value = dataItem;
            }

            if (search_value && media_type) {
              selected_item = kendo.format(seach_redirect_template, media_type, encodeURIComponent(search_value));
            } else if (search_value) {
              selected_item = kendo.format(seach_redirect_template, '', encodeURIComponent(search_value));
            } else {
              selected_item = kendo.format(seach_redirect_template, '', encodeURIComponent(dataItem));
              search_value = dataItem;
            }
          // This is the returned items from a search
          } else {
            switch(dataItem.media_type) {
              case 'movie':
                selected_item = kendo.format(seach_redirect_template, '/movie', encodeURIComponent(dataItem.name));
                search_value = dataItem.name;
                break;
              case 'tv':
                selected_item = kendo.format(seach_redirect_template, '/tv', encodeURIComponent(dataItem.name));
                search_value = dataItem.name;
                break;
              case 'person':
                selected_item = kendo.format(seach_redirect_template, '/person', encodeURIComponent(dataItem.name));
                search_value = dataItem.name;
                break;
              default:
                selected_item = kendo.format(seach_redirect_template, '', encodeURIComponent(dataItem));
                search_value = dataItem;
            }
          }

          $("#search_v4").data("kendoAutoComplete").value(search_value);
          executeSearch(selected_item);
        }

        $("#search_v4").kendoAutoComplete({
          highlightFirst: false,
          minLength: 1,
          dataTextField: "title",
          template: kendo.template($("#slim_multi_search_template").html()),
          noDataTemplate: $("#search_no_data_template").html(),
          dataSource: {
            serverFiltering: true,
            transport: {
              read: '/search/trending',
              parameterMap: function() {
                return { query: $("#search_v4").data("kendoAutoComplete").value() };
              }
            },
            schema: {
              data: "results"
            }
          },
          popup: {
            appendTo: $("section.search")
          },
          filtering: function(e) {
            var filter = e.filter != undefined ? e.filter.value : "";
            if (filter == '') {
              if ( ($('#search_v4-list #trending_search_header_template').length) == 0 ) {
                // $('#search_v4_listbox').empty();
                $('#search_v4-list').prepend($("#search_v4_headerTemplate").html());
              }
            } else {
              $("#trending_search_header_template").remove();
            }
          },
          select: function(e) {
            processing_selected_item = true;
            processSelectedItem(e);
          },
          close: function(e) {
            // Use this to prevent the popup from closing in dev.
            // e.preventDefault();
          }
        }).data("kendoAutoComplete");

        $('#search_v4').keydown(function(event) {
          if (event.keyCode == 13) {
            if (processing_selected_item) {
              return;
            } else {
              processSelectedItem(null);
            }
          }
        });

        $('header #search_form').submit(function() {
          return false;
        });

        var autocompleteInput = $('section.search .k-autocomplete input');
        autocompleteInput.on('focus', function (e) {
          var value = autocompleteInput.val();
          if (value == null || value == '') {
            $("#search_v4").data("kendoAutoComplete").search('');
          } else {
            var fieldLength = value.length;
            autocompleteInput[0].setSelectionRange(fieldLength, fieldLength);
          }
        });

        $('header.show_search_false li.search_buttons a.search').on('click', function(e) {
          e.preventDefault();
          showSearch(true);
        });

        $('header.show_search_true li.search_buttons a.search').on('click', function(e) {
          e.preventDefault();
          $("#search_v4").data("kendoAutoComplete").focus();
        });

        $('header.show_search_false li.search_buttons a.close').on('click', function(e) {
          e.preventDefault();
          showSearch(false);
        });

        $('main.show_search_false').on('click', function(e) {
          showSearch(false);
        });

        $('header span.k-i-close[title="clear"]').on('click', function(e) {
          $('#search_v4').data("kendoAutoComplete").focus();
        });

          $("body").on('click', 'a.report', function(e) {
            e.preventDefault();

            var media_type = $(this).data("media-type");
            var media_id = $(this).data("media-id");
            var request_url = encodeURIComponent($(this).data("media-url"));
            var url_template = '/report/new?media_type={0}&media_id={1}&request_url={2}';

            $("#report_window").kendoWindow({
              content: kendo.format(url_template, media_type, media_id, request_url),
              title: 'Report an Issue',
              modal: true,
              draggable: false,
              resizable: false,
              width: mobileDevice ? "95%" : 700,
              height: mobileDevice ? "95%" : 500,
              visible: false,
              pinned: true,
              animation: {
                open: {
                  effects: "fade:in"
                },
                close: {
                  effects: "fade:out"
                }
              },
              open: function() {
                $('body').addClass('monochrome');
              },
              close: function() {
                $('body').removeClass('monochrome');
              }
            }).data("kendoWindow").center().open();
          });

          var opened_notification = false;
          $("header li.notifications, div.left_column li.notifications").kendoTooltip({
            autoHide: false,
            content: {
              url: "/notifications?referrer=%2Fsearch",
              cache: true
            },
            showOn: 'click',
            width: 300,
            position: 'bottom',
            contentLoad: function(e) {
              this.popup.element.parent().parent().css("height", "100%");
              this.popup.element.parent().css("height", "100%");
            },
            show: function(e) {
              if (opened_notification) {
                this.refresh();
              }
              opened_notification = true;

              $("div.k-tooltip-button").addClass('hide');
              this.popup.element.addClass("min_100px_height tmdb_theme_white");
            }
          });

          pageLoaded().then(function() {
            pusher_account_channel.then(function(channel) {
              channel.bind('general', function(data) {
                if (data.unread_count == 0) {
                  $('li.notifications a span').removeClass('on');
                  $('li.notifications div.badge').addClass('hide');
                } else {
                  $('li.notifications div.badge div.count').html(data.unread_count);
                  $('li.notifications a span').addClass('on');
                  $('li.notifications div.badge').removeClass('hide');
                }
              });
            });
          });

          delete_window = $("
").kendoWindow({
            title: "Confirm",
            width: "240px",
            resizable: false,
            modal: true,
            animation: {
              open: {
                effects: "fade:in"
              },
              close: {
                effects: "fade:out"
              }
            },
            open: function() {
              $('body').addClass('monochrome');
            },
            close: function() {
              $('body').removeClass('monochrome');
            }
          });

        public_media_type_map = {
          'movie': 'Movie',
          'tv': 'TV Show',
          'person': 'Person'
        };

          $(document).on('keydown', null, 'e', function() {
            if ( $('a.keyboard_s.edit_page').length ) {
              $('a.keyboard_s.edit_page')[0].click();
            }
          });

          $(document).on('keydown', null, 'a', function() {
            if ( $('a.keyboard_s.add_image').length ) {
              $('a.keyboard_s.add_image')[0].click();
            }
          });

          $(document).on('keydown', null, 'l', function() {
            if ( $('a.keyboard_s.lock_all').length ) {
              $('a.keyboard_s.lock_all')[0].click();
            }
          });

          $(document).on('keydown', null, 'ctrl+s', function() {
            if ( $('input.keyboard_s.save').length ) {
              $('input.keyboard_s.save').click();
            }
          });

          $(document).on('keydown', null, 't', function() {
            if ( $('#edit_translation_selector').length ) {
              $("#edit_translation_selector").data("kendoDropDownList").open();
            }
          });

          $(document).on('keydown', null, 'p', function() {
            $('header ul.primary li.user a').addClass('keyboard');
            $('header ul.primary li.user a').click();
          });

        $(document).on('keydown', null, 'b', function() {
          if ( $('a.keyboard_s.parent').length ) {
            $('a.keyboard_s.parent')[0].click();
          }
        });

        $(document).on('keyup', null, 's', function() {
          if ( $('#search_v4').length ) {
            if ( $('header').hasClass('show_search_false') ) {
              showSearch(true);
            } else {
              $("#search_v4").data("kendoAutoComplete").focus();
            }
          }
        });

        $(document).on('keyup', null, 'shift+/', function() {
          keyboard_shortcut_popup.open();
        });

        $(document).on('keydown', null, 'left', function() {
          if ( $('span.previous a.keyboard_s').length ) {
            $('span.previous a.keyboard_s')[0].click();
          }
        });

        $(document).on('keydown', null, 'right', function() {
          if ( $('span.next a.keyboard_s').length ) {
            $('span.next a.keyboard_s')[0].click();
          }
        });

        $(document).on('keydown', null, 'm', function() {
          if ( $('#new_shortcut_bar').length ) {
            $("#new_shortcut_bar").focus();
          }
        });
      });

      var gender_lookup = {
        0: 'two',
        1: 'one',
        2: 'two',
        3: 'two'
      }
